import{_ as e,o as d,c as a,ae as o}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Workflow State Contract（工作流状态机合同）","description":"","frontmatter":{},"headers":[],"relativePath":"reference/contracts/workflow-state.md","filePath":"reference/contracts/workflow-state.md"}'),i={name:"reference/contracts/workflow-state.md"};function r(c,t,s,n,l,h){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="workflow-state-contract-工作流状态机合同" tabindex="-1">Workflow State Contract（工作流状态机合同） <a class="header-anchor" href="#workflow-state-contract-工作流状态机合同" aria-label="Permalink to &quot;Workflow State Contract（工作流状态机合同）&quot;">​</a></h1><blockquote><p>Defines phase sets, transition rules, terminal states, and counter invariants for ralph, autopilot, and team modes.</p><p>This contract extends the <a href="./state-contract.html">State Contract</a> with mode-specific rules.</p></blockquote><h2 id="ralph-持久化执行循环" tabindex="-1">Ralph（持久化执行循环） <a class="header-anchor" href="#ralph-持久化执行循环" aria-label="Permalink to &quot;Ralph（持久化执行循环）&quot;">​</a></h2><h3 id="phase-set" tabindex="-1">Phase Set <a class="header-anchor" href="#phase-set" aria-label="Permalink to &quot;Phase Set&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>init → planning → executing → verifying ↔ fixing → complete | failed</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Phase</th><th>Description</th></tr></thead><tbody><tr><td><code>init</code></td><td>Initial state; write task description and parameters</td></tr><tr><td><code>planning</code></td><td>Analyze task, identify success criteria, produce execution plan</td></tr><tr><td><code>executing</code></td><td>Carry out the plan; write progress after each significant step</td></tr><tr><td><code>verifying</code></td><td>Check all success criteria; run tests, lint, typecheck</td></tr><tr><td><code>fixing</code></td><td>Diagnose and fix verification failures; increment <code>fix_attempt</code></td></tr><tr><td><code>complete</code></td><td>All criteria met（终态：成功）</td></tr><tr><td><code>failed</code></td><td>Max iterations exhausted（终态：失败）</td></tr></tbody></table><h3 id="status-field" tabindex="-1">Status Field <a class="header-anchor" href="#status-field" aria-label="Permalink to &quot;Status Field&quot;">​</a></h3><p><code>status</code> (string, lowercased)</p><h3 id="counters" tabindex="-1">Counters <a class="header-anchor" href="#counters" aria-label="Permalink to &quot;Counters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Counter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>iteration</code></td><td>non-negative int</td><td><code>0</code></td><td>Current retry iteration</td></tr><tr><td><code>max_iterations</code></td><td>positive int</td><td><code>10</code></td><td>Maximum retry iterations before failure</td></tr><tr><td><code>fix_attempt</code></td><td>non-negative int</td><td><code>0</code></td><td>Fix attempts within current iteration</td></tr><tr><td><code>max_fix_attempts</code></td><td>positive int</td><td><code>3</code></td><td>Max fixes before restarting iteration</td></tr></tbody></table><h3 id="retry-logic" tabindex="-1">Retry Logic <a class="header-anchor" href="#retry-logic" aria-label="Permalink to &quot;Retry Logic&quot;">​</a></h3><ul><li>FIXING exceeds <code>max_fix_attempts</code> → increment <code>iteration</code>, restart from PLANNING with <code>lessons</code> carried forward</li><li><code>iteration</code> exceeds <code>max_iterations</code> → <code>status=failed</code>, <code>active=false</code></li></ul><h3 id="additional-fields" tabindex="-1">Additional Fields <a class="header-anchor" href="#additional-fields" aria-label="Permalink to &quot;Additional Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>task</code></td><td>string</td><td>Original task description</td></tr><tr><td><code>lessons</code></td><td>string[]</td><td>Accumulated lessons from failed iterations</td></tr><tr><td><code>mode</code></td><td><code>&quot;ralph&quot;</code></td><td>Mode identifier</td></tr></tbody></table><hr><h2 id="autopilot-自主执行流水线" tabindex="-1">Autopilot（自主执行流水线） <a class="header-anchor" href="#autopilot-自主执行流水线" aria-label="Permalink to &quot;Autopilot（自主执行流水线）&quot;">​</a></h2><h3 id="phase-set-1" tabindex="-1">Phase Set <a class="header-anchor" href="#phase-set-1" aria-label="Permalink to &quot;Phase Set&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>analyzing → planning → executing → verifying ↔ retry → complete | blocked | failed</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Phase</th><th>Description</th></tr></thead><tbody><tr><td><code>analyzing</code></td><td>Explore codebase to understand current state relevant to goal</td></tr><tr><td><code>planning</code></td><td>Generate numbered step list with per-step success criteria</td></tr><tr><td><code>executing</code></td><td>Execute current step; write progress after each step</td></tr><tr><td><code>verifying</code></td><td>End-to-end verification against original goal</td></tr><tr><td><code>retry</code></td><td>Diagnose step failure; retry with different strategy</td></tr><tr><td><code>complete</code></td><td>Goal achieved（终态：成功）</td></tr><tr><td><code>blocked</code></td><td>Step exhausted retries（终态：阻塞，需人工介入）</td></tr><tr><td><code>failed</code></td><td>Unrecoverable failure（终态：失败）</td></tr></tbody></table><h3 id="status-field-1" tabindex="-1">Status Field <a class="header-anchor" href="#status-field-1" aria-label="Permalink to &quot;Status Field&quot;">​</a></h3><p><code>status</code> (string, lowercased)</p><h3 id="counters-1" tabindex="-1">Counters <a class="header-anchor" href="#counters-1" aria-label="Permalink to &quot;Counters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Counter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>current_step</code></td><td>non-negative int</td><td><code>0</code></td><td>Index of current step being executed</td></tr><tr><td><code>total_steps</code></td><td>non-negative int</td><td><code>0</code></td><td>Total steps in plan</td></tr><tr><td><code>max_retries_per_step</code></td><td>positive int</td><td><code>3</code></td><td>Max retries before blocking on a step</td></tr></tbody></table><h3 id="execution-rules" tabindex="-1">Execution Rules <a class="header-anchor" href="#execution-rules" aria-label="Permalink to &quot;Execution Rules&quot;">​</a></h3><ul><li>One step at a time, sequentially</li><li>Verify each step before advancing</li><li>On failure, retry with a <strong>different</strong> strategy (never repeat the same approach)</li><li>Retries exhausted → <code>status=blocked</code></li></ul><h3 id="additional-fields-1" tabindex="-1">Additional Fields <a class="header-anchor" href="#additional-fields-1" aria-label="Permalink to &quot;Additional Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>goal</code></td><td>string</td><td>Original goal description</td></tr><tr><td><code>plan</code></td><td>object[]</td><td>Step list: <code>{ step, description, status, retries, summary? }</code></td></tr><tr><td><code>mode</code></td><td><code>&quot;autopilot&quot;</code></td><td>Mode identifier</td></tr></tbody></table><hr><h2 id="team-多智能体团队桥接" tabindex="-1">Team（多智能体团队桥接） <a class="header-anchor" href="#team-多智能体团队桥接" aria-label="Permalink to &quot;Team（多智能体团队桥接）&quot;">​</a></h2><h3 id="phase-set-2" tabindex="-1">Phase Set <a class="header-anchor" href="#phase-set-2" aria-label="Permalink to &quot;Phase Set&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>planning → decomposing → delegating → executing → verifying ↔ fixing → complete | failed</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Phase</th><th>Description</th></tr></thead><tbody><tr><td><code>planning</code></td><td>Initial phase; receive task and determine agent configuration</td></tr><tr><td><code>decomposing</code></td><td>Break task into subtasks for parallel workers</td></tr><tr><td><code>delegating</code></td><td>Upstream team skill is in control（已委托宿主）</td></tr><tr><td><code>executing</code></td><td>Workers are executing subtasks</td></tr><tr><td><code>verifying</code></td><td>Verify combined results meet acceptance criteria</td></tr><tr><td><code>fixing</code></td><td>Fix verification failures; increment <code>fix_loop_count</code></td></tr><tr><td><code>complete</code></td><td>All subtasks verified（终态：成功）</td></tr><tr><td><code>failed</code></td><td>Max fix loops exhausted or upstream failure（终态：失败）</td></tr></tbody></table><h3 id="status-field-2" tabindex="-1">Status Field <a class="header-anchor" href="#status-field-2" aria-label="Permalink to &quot;Status Field&quot;">​</a></h3><p><code>current_phase</code> (string, lowercased) — <strong>not</strong> <code>status</code></p><blockquote><p>Team uses <code>current_phase</code> instead of <code>status</code> to avoid collision with the host team skill&#39;s own status tracking.</p></blockquote><h3 id="counters-2" tabindex="-1">Counters <a class="header-anchor" href="#counters-2" aria-label="Permalink to &quot;Counters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Counter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>fix_loop_count</code></td><td>non-negative int</td><td><code>0</code></td><td>Number of verify-fix cycles completed</td></tr><tr><td><code>max_fix_loops</code></td><td>positive int</td><td><code>3</code></td><td>Maximum verify-fix cycles before failure</td></tr></tbody></table><h3 id="additional-fields-2" tabindex="-1">Additional Fields <a class="header-anchor" href="#additional-fields-2" aria-label="Permalink to &quot;Additional Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>task</code></td><td>string</td><td>Original task description</td></tr><tr><td><code>agent_count</code></td><td>number</td><td>Number of parallel agents requested</td></tr><tr><td><code>subtasks</code></td><td>object[]</td><td>Decomposed subtask list</td></tr><tr><td><code>linked_ralph</code></td><td>boolean</td><td><code>true</code> when invoked from within ralph; ralph handles retry on team failure</td></tr><tr><td><code>mode</code></td><td><code>&quot;team&quot;</code></td><td>Mode identifier</td></tr></tbody></table><hr><h2 id="shared-terminal-rules-共享终态规则" tabindex="-1">Shared Terminal Rules（共享终态规则） <a class="header-anchor" href="#shared-terminal-rules-共享终态规则" aria-label="Permalink to &quot;Shared Terminal Rules（共享终态规则）&quot;">​</a></h2><p>Terminal phases: <code>complete</code>, <code>failed</code>, <code>blocked</code></p><table tabindex="0"><thead><tr><th>Rule</th><th>Enforcement</th></tr></thead><tbody><tr><td>Terminal phase + <code>active=true</code></td><td><strong>Rejected</strong> — validation returns error</td></tr><tr><td>Terminal phase + missing <code>completedAt</code></td><td><strong>Auto-set</strong> to current ISO8601 timestamp</td></tr><tr><td>Non-terminal phase + <code>active=false</code></td><td>Allowed (paused/suspended state)</td></tr></tbody></table><h2 id="timestamp-invariants-时间戳不变量" tabindex="-1">Timestamp Invariants（时间戳不变量） <a class="header-anchor" href="#timestamp-invariants-时间戳不变量" aria-label="Permalink to &quot;Timestamp Invariants（时间戳不变量）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Auto-set When</th><th>Format</th></tr></thead><tbody><tr><td><code>startedAt</code></td><td><code>active=true</code> first written and field is null</td><td>ISO8601</td></tr><tr><td><code>completedAt</code></td><td>Terminal phase reached and field is null</td><td>ISO8601</td></tr><tr><td><code>lastUpdatedAt</code></td><td>Every successful write</td><td>ISO8601</td></tr></tbody></table><h2 id="default-injection-默认值注入" tabindex="-1">Default Injection（默认值注入） <a class="header-anchor" href="#default-injection-默认值注入" aria-label="Permalink to &quot;Default Injection（默认值注入）&quot;">​</a></h2><p>When <code>active=true</code> and fields are null, validators inject defaults:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Injected Defaults</th></tr></thead><tbody><tr><td>ralph</td><td><code>iteration=0</code>, <code>max_iterations=10</code>, <code>fix_attempt=0</code>, <code>max_fix_attempts=3</code>, <code>status=&quot;init&quot;</code>, <code>startedAt=now</code></td></tr><tr><td>autopilot</td><td><code>current_step=0</code>, <code>total_steps=0</code>, <code>max_retries_per_step=3</code>, <code>status=&quot;analyzing&quot;</code>, <code>startedAt=now</code></td></tr><tr><td>team</td><td><code>fix_loop_count=0</code>, <code>max_fix_loops=3</code>, <code>current_phase=&quot;planning&quot;</code>, <code>startedAt=now</code></td></tr></tbody></table><h2 id="workflow-exclusivity-guard-工作流互斥" tabindex="-1">Workflow Exclusivity Guard（工作流互斥） <a class="header-anchor" href="#workflow-exclusivity-guard-工作流互斥" aria-label="Permalink to &quot;Workflow Exclusivity Guard（工作流互斥）&quot;">​</a></h2><p>Only one of <code>ralph</code>, <code>autopilot</code>, <code>team</code> may have <code>active=true</code> at any time. Enforced by <code>assertWorkflowExclusivity()</code> in <code>omm-packages/omm-plugin/src/omm-workflow-guard.ts</code> and mirrored inline in <code>omm-packages/omm-mcp/src/index.ts</code>.</p><p><strong>Rules:</strong></p><ul><li>A workflow write with <code>active !== true</code> always passes through.</li><li>A non-workflow key (anything other than <code>ralph</code>/<code>autopilot</code>/<code>team</code> after <code>value.mode ?? key</code> resolution) always passes through.</li><li>Same-key overwrites are allowed (re-activating the same mode).</li><li><strong>Linked exception (unidirectional):</strong> <code>team</code> writes <code>linked_ralph: true</code> to declare it was launched inside a ralph persistence loop. In that case ralph and team may both be active simultaneously. Ralph itself never writes any linkage field. <ul><li>Incoming <code>ralph</code> + existing <code>team</code> with <code>linked_ralph === true</code> → allowed</li><li>Incoming <code>team</code> with <code>linked_ralph === true</code> + existing <code>ralph</code> → allowed</li><li>All other combinations of two active workflow modes → rejected with <code>cannot activate &lt;mode&gt;: &lt;other&gt; is already active</code>.</li></ul></li></ul><p><strong>Failure-safe defaults:</strong></p><ul><li>State directory missing → no conflict, write allowed.</li><li>Individual JSON file unreadable or corrupt → that file is skipped (not treated as a conflict).</li></ul><p><strong>Race window:</strong> the check is read-then-write without locking. For omm&#39;s single-user desktop deployment this is acceptable. Multi-session deployments would need a <code>state/.lock</code> file with <code>O_EXCL</code> semantics.</p><p>See <a href="./../adr/004-three-mode-state-machine.html">ADR-004</a>.</p>',56)])])}const f=e(i,[["render",r]]);export{p as __pageData,f as default};
